-- Saved & shared prototypes (website and app). Visitors save a prototype they generated by leaving their
-- name and a WhatsApp number or email; the server (service role, /api/prototype-share) inserts the row after
-- checking the HTML's generation signature. The public can only open a prototype through
-- prototype_share_public(slug), which never returns contact details. Staff read rows like other enquiries.

CREATE TABLE IF NOT EXISTS public.prototype_shares (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE CHECK (slug ~ '^[A-Za-z0-9]{10,16}$'),
  kind text NOT NULL CHECK (kind IN ('website', 'app')),
  title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120),
  prompt text NOT NULL CHECK (char_length(prompt) BETWEEN 1 AND 600),
  plan jsonb,
  html text NOT NULL CHECK (char_length(html) BETWEEN 50 AND 250000),
  logo text CHECK (logo IS NULL OR (logo ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' AND char_length(logo) <= 200000)),
  platform text CHECK (platform IS NULL OR platform IN ('ios', 'android')),
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  business text CHECK (business IS NULL OR char_length(business) <= 120),
  email text CHECK (email IS NULL OR (char_length(email) <= 200 AND email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$')),
  whatsapp text CHECK (whatsapp IS NULL OR whatsapp ~ '^\+?[0-9 ()-]{7,22}$'),
  suggested_plan text,
  consent boolean NOT NULL CHECK (consent),
  visitor_hash text,
  views integer NOT NULL DEFAULT 0,
  last_viewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (email IS NOT NULL OR whatsapp IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS prototype_shares_created_idx ON public.prototype_shares (created_at DESC);

ALTER TABLE public.prototype_shares ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.prototype_shares FROM anon, authenticated;
GRANT SELECT ON public.prototype_shares TO authenticated;

DROP POLICY IF EXISTS "staff read prototype shares" ON public.prototype_shares;
CREATE POLICY "staff read prototype shares" ON public.prototype_shares
  FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.site_can('enquiries.read'::text));

-- Public view of one saved prototype: no contact details, counts the view.
CREATE OR REPLACE FUNCTION public.prototype_share_public(p_slug text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE r public.prototype_shares;
BEGIN
  IF p_slug IS NULL OR p_slug !~ '^[A-Za-z0-9]{10,16}$' THEN RETURN NULL; END IF;
  UPDATE public.prototype_shares SET views = views + 1, last_viewed_at = now()
    WHERE slug = p_slug RETURNING * INTO r;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'slug', r.slug, 'kind', r.kind, 'title', r.title, 'html', r.html, 'logo', r.logo,
    'platform', coalesce(r.platform, 'ios'),
    'plan', CASE WHEN r.plan IS NULL THEN NULL ELSE jsonb_build_object(
      'name', r.plan->'name', 'primary', r.plan->'primary', 'accent', r.plan->'accent', 'screens', r.plan->'screens') END,
    'suggested_plan', r.suggested_plan,
    'created_at', r.created_at);
END $$;

REVOKE ALL ON FUNCTION public.prototype_share_public(text) FROM public;
GRANT EXECUTE ON FUNCTION public.prototype_share_public(text) TO anon, authenticated;

-- Owner alert: a short email with who saved what and the link (never the HTML itself).
CREATE OR REPLACE FUNCTION public.prototype_share_alert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE site text; link text; digits text; wa text := '';
BEGIN
  SELECT site_url INTO site FROM public.blog_settings LIMIT 1;
  link := rtrim(coalesce(site, 'https://emmaforyou.lovable.app'), '/') || '/p/' || NEW.slug;
  digits := regexp_replace(coalesce(NEW.whatsapp, ''), '\D', '', 'g');
  IF length(digits) = 11 AND left(digits, 1) = '0' THEN digits := '234' || substr(digits, 2); END IF;
  IF length(digits) >= 8 THEN
    wa := '<p><a href="https://wa.me/' || digits || '" style="background:#25d366;color:#fff;padding:10px 18px;border-radius:999px;text-decoration:none;font-weight:600">Reply on WhatsApp</a></p>';
  END IF;
  PERFORM public.owner_alert_send('prototype_shares',
    'New ' || NEW.kind || ' prototype saved: ' || NEW.name,
    '<h2 style="margin:0 0 4px">New ' || NEW.kind || ' prototype saved</h2>' ||
    '<p style="margin:0 0 12px;color:#6b7280">' || public.owner_alert_esc(NEW.title) || '</p>' || wa ||
    '<table style="border-collapse:collapse;font-size:14px">' ||
    '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Name</td><td>' || public.owner_alert_esc(NEW.name) || '</td></tr>' ||
    '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Business</td><td>' || public.owner_alert_esc(coalesce(NEW.business, '')) || '</td></tr>' ||
    '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">WhatsApp</td><td>' || public.owner_alert_esc(coalesce(NEW.whatsapp, '')) || '</td></tr>' ||
    '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Email</td><td>' || public.owner_alert_esc(coalesce(NEW.email, '')) || '</td></tr>' ||
    '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">They asked for</td><td>' || public.owner_alert_esc(NEW.prompt) || '</td></tr>' ||
    '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Suggested plan</td><td>' || public.owner_alert_esc(coalesce(NEW.suggested_plan, '')) || '</td></tr>' ||
    '</table><p><a href="' || link || '">Open their prototype</a></p>');
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS prototype_share_alert ON public.prototype_shares;
CREATE TRIGGER prototype_share_alert AFTER INSERT ON public.prototype_shares
  FOR EACH ROW EXECUTE FUNCTION public.prototype_share_alert();
